Definition critical_factorization_low_level_spec_entail_long_needle_bind_spec :=
forall (C: Type),
forall (needle_pre: Z) (needle_len_pre: Z) (period_pre: Z) (needle0_long_needle_bind_spec: (@list Z)) (n0_long_needle_bind_spec: Z) (X_long_needle_bind_spec: (C -> (unit -> Prop))) (f_long_needle_bind_spec: ((Z * Z) -> (@ MonadErr.M  unit C))),
  (“ (safeExec ATrue (bind ((critical_factorization_prog (needle0_long_needle_bind_spec))) (f_long_needle_bind_spec)) X_long_needle_bind_spec ) ”
  &&  “ (needle_len_pre = n0_long_needle_bind_spec) ”
  &&  “ (0 < needle_len_pre) ”
  &&  “ (needle_len_pre <= INT_MAX) ”
  &&  (UCharArray.full needle_pre needle_len_pre needle0_long_needle_bind_spec )
  **  ((period_pre) # Int  |->_))
